#include <bits/stdc++.h>
using namespace std;

int digitSum(int n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long k;
    cin >> k;

    for (int i = 1; i < 100000000; ++i) {
        if (digitSum(i) == 10 && --k == 0) {
            cout << i;
            break;
        }
    }

    return 0;
}

